<?php

declare(strict_types=1);

use Byteworks\SonataThemeBundle\Controller\ColorsController;
use Symfony\Component\Routing\Loader\Configurator\RoutingConfigurator;

/*
 * Routes of the theme. Needed for the application's own colors (option "colors"): the stylesheet, generated by a
 * controller, under the path of the theme's assets. It must be reachable without login, since the login page uses
 * it too. Not colors.css: that is a static file of the theme (the palette), and web servers serve existing files
 * first; a missing file under /bundles/ has to reach the front controller. An application can define a route of
 * this name itself to put the stylesheet elsewhere; the templates link it by the name.
 */
return static function (RoutingConfigurator $routes): void {
    $routes->add('byteworks_sonata_theme_colors', '/bundles/byteworkssonatatheme/custom-colors.css')
        ->controller(ColorsController::class)
        ->methods(['GET', 'HEAD']);
};
